// scripts/lib/reply-draft-text.mjs — the reply text inside a `<!-- reply-draft -->` comment.
//
// A draft comment is: the marker line, the "**Reply draft** — …" header line, a blank line, the
// reply, and often a footer that the comment tooling appends ("---" then "_Generated by …_").
// Only the reply goes to the store. On 2026-10-25 the #600 dry run showed the footer (and its
// link) inside the text that `post` would send to App Store Connect.

const FOOTER = /\n-{3,}\s*\n+\s*_Generated by [^\n]*_\s*$/;

export function draftTextOf(commentBody) {
  return String(commentBody || '')
    .split('\n')
    .slice(1)
    .join('\n')
    .replace(/^\*\*Reply draft\*\*[^\n]*\n\n?/, '')
    .replace(FOOTER, '')
    .trim();
}

export function hasLink(text) {
  return /https?:\/\//i.test(String(text || ''));
}
